package cr.logisticaportuaria.shared.persistence;

import cr.logisticaportuaria.shared.domain.UuidV7;
import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PostLoad;
import jakarta.persistence.PostPersist;
import jakarta.persistence.Transient;
import java.util.UUID;
import org.springframework.data.domain.Persistable;

/**
 * Base of every entity of the system.
 *
 * <p>The identifiers are UUID v7 generated by the application, so an entity
 * that has just been created already carries an identifier. Spring Data would
 * take it for an existing row, call {@code merge} instead of {@code persist}
 * and the caller would keep working with a <em>detached</em> copy: everything
 * changed after {@code save} would be silently lost. Implementing
 * {@link Persistable} tells Spring Data which entities are new, so {@code save}
 * uses {@code persist} and the returned instance is the managed one.
 */
@MappedSuperclass
public abstract class AbstractEntity implements Persistable<UUID> {

    @Id
    @Column(name = "id", nullable = false, updatable = false)
    private UUID id = UuidV7.random();

    @Transient
    private boolean isNew = true;

    @Override
    public UUID getId() {
        return id;
    }

    @Override
    public boolean isNew() {
        return isNew;
    }

    /**
     * Marks the entity as already stored: from this point {@code save} behaves
     * like an update.
     */
    @PostLoad
    @PostPersist
    protected void markPersisted() {
        this.isNew = false;
    }
}
